import time

class StaleFencingTokenError(Exception):
    """Raised when a storage write arrives with a stale or out-of-order fencing token."""

class DistributedLockService:
    def __init__(self, lease_ttl=10.0, clock=time.monotonic):
        self._lease_ttl = lease_ttl
        self._clock = clock
        self._current_holder = None
        self._expires_at = 0.0
        self._token_counter = 0
        self._current_token = 0

    def acquire(self, client_id):
        now = self._clock()
        if self._current_holder is not None and now < self._expires_at:
            if self._current_holder == client_id:
                return self._current_token
            return None
        self._token_counter += 1
        self._current_token = self._token_counter
        self._current_holder = client_id
        self._expires_at = now + self._lease_ttl
        return self._current_token

    def release(self, client_id, token):
        if self._current_holder == client_id and self._current_token == token:
            self._current_holder = None
            self._expires_at = 0.0
            return True
        return False

    def is_locked(self):
        now = self._clock()
        return self._current_holder is not None and now < self._expires_at

class FencedStorage:
    def __init__(self):
        self._store = {}
        self._last_token = 0

    def write(self, key, value, token):
        if token <= self._last_token:
            raise StaleFencingTokenError(f"Stale token {token} <= last seen {self._last_token}")
        self._last_token = token
        self._store[key] = value
        return True

    def get(self, key):
        return self._store.get(key)

    def last_token(self):
        return self._last_token
